SELECT * FROM ( SELECT APP_VER_NO, OS_TYPE, LATEST_VERSION, MIN_VERSION, UPDATE_MSG, STORE_URL, USE_YN, REGUSR_NO, DATE_FORMAT(REGIST_DT, '%Y-%m-%d %H:%i:%s') AS REGIST_DT, UPDFUSR_NO, DATE_FORMAT(UPDT_DT, '%Y-%m-%d %H:%i:%s') AS UPDT_DT FROM tb_app_version WHERE 1=1
AND OS_TYPE = #{OS_TYPE}
AND USE_YN = #{USE_YN}
ORDER BY REGIST_DT DESC ) A LIMIT #{limitStart}, #{limitEnd}
